p.write_text('''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for color in range(10):
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr,dc in ((1,1),(1,-1)):
            groups = {}
            for r,c in pts:
                key = c - dc*r
                groups.setdefault(key, []).append((r,c))
            for group in groups.values():
                if len(group) < 2:
                    continue
                group.sort()
                # Extend only a perfectly consecutive diagonal.
                if any((b[0]-a[0], b[1]-a[1]) != (1,dc) for a,b in zip(group,group[1:])):
                    continue
                for r,c,step in ((group[0][0]-dr, group[0][1]-dc, -1), (group[-1][0]+dr, group[-1][1]+dc, 1)):
                    while 0 <= r < h and 0 <= c < w and grid[r][c] == 6 and color != 6:
                        out[r][c] = color
                        r += step*dr; c += step*dc
    return out
''')
